import {VARIABLES,AREAS,getSeries,isUsable,seasonalAnomalies,annualSummaries,assessTrend,validateDataset,summarizeQuality} from './science.js';
import {createMap,MAP_AREAS} from './map.js';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const state={area:'seco',variable:'ndvi',start:2015,end:2025,compare:2025,page:'overview',imported:null,table:false};
const months=['E','F','M','A','M','J','J','A','S','O','N','D'];
const fullMonths=['enero','febrero','marzo','abril','mayo','junio','julio','agosto','septiembre','octubre','noviembre','diciembre'];
const mean=rows=>rows.length?rows.reduce((s,r)=>s+r.value,0)/rows.length:null;
const fmt=(n,d=2)=>Number.isFinite(n)?n.toLocaleString('es-AR',{minimumFractionDigits:d,maximumFractionDigits:d}):'—';
const unit=v=>({ndvi:'índice',evi:'índice',precip:'mm/mes',hotspots:'detecciones/mes',soil:'m³/m³'}[v]);
const annualUnit=v=>({ndvi:'puntos de índice',evi:'puntos de índice',precip:'mm/año',hotspots:'detecciones/año',soil:'m³/m³'}[v]);
const fullSeries=(v=state.variable,a=state.area)=>state.imported?(state.imported.variable===v&&state.imported.area===a?state.imported.points:[]):getSeries(v,a);
const visibleSeries=(v=state.variable)=>fullSeries(v).filter(p=>+p.date.slice(0,4)>=state.start&&+p.date.slice(0,4)<=state.end);
const labelMode=()=>state.imported?'Importado · fuente declarada':'Demo · serie sintética';
const toast=message=>{clearTimeout(toast.timer);$('#toast').textContent=message;$('#toast').hidden=false;toast.timer=setTimeout(()=>$('#toast').hidden=true,5000);};
function download(name,text,type='text/plain;charset=utf-8'){const blob=new Blob([text],{type});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function syncYears(){const all=state.imported?state.imported.points.map(p=>+p.date.slice(0,4)):Array.from({length:11},(_,i)=>2015+i);const years=[...new Set(all)].sort((a,b)=>a-b);for(const [id,key] of [['start-year','start'],['end-year','end']]){$('#'+id).innerHTML=years.map(y=>`<option value="${y}">${y}</option>`).join('');$('#'+id).value=state[key];}const compareYears=years.filter(y=>y>=state.start&&y<=state.end);if(!compareYears.includes(state.compare))state.compare=compareYears.at(-1);$('#compare-year').innerHTML=compareYears.map(y=>`<option value="${y}">${y}</option>`).join('');$('#compare-year').value=state.compare;}
function navigate(page,scroll=true){state.page=page;$$('.nav-item').forEach(b=>b.classList.toggle('active',b.dataset.page===page));$$('.page-view').forEach(p=>p.hidden=p.id!==`page-${page}`);$('#analysis-shared').hidden=!['overview','analysis'].includes(page);if(scroll)window.scrollTo({top:0,behavior:'instant'});}
const map=createMap($('#map'),{onSelect:id=>{if(state.imported&&id!==state.imported.area){toast('Esta serie importada corresponde a otra área. Volvé a demo para explorar las tres.');map.setSelection(state.area);return;}state.area=id;render();}});
function renderMetrics(){const cards=[[(state.variable==='evi'?'evi':'ndvi'),'♧',(state.variable==='evi'?'Vegetación · EVI':'Vegetación · NDVI')],['precip','≋','Precipitación'],['hotspots','♨','Focos de calor'],['soil','◒','Humedad del suelo']];$('#metric-grid').innerHTML=cards.map(([v,icon,name])=>{const usable=visibleSeries(v).filter(isUsable);const value=mean(usable);const selected=state.variable===v||(state.variable==='evi'&&v==='ndvi');return `<button class="metric ${selected?'selected':''}" data-metric="${v}" aria-pressed="${selected}"><span class="metric-top"><span class="metric-icon">${icon}</span>${name}</span><span class="metric-value">${fmt(value,VARIABLES[v].decimals)}</span><span class="metric-unit">${unit(v)}</span><span class="metric-detail"><span>Promedio mensual · ${state.start}–${state.end}</span><em>${state.imported?'IMPORTADO':'DEMO'}</em></span></button>`;}).join('');$$('[data-metric]').forEach(b=>b.addEventListener('click',()=>selectVariable(b.dataset.metric)));}
function selectVariable(v){if(state.imported&&state.imported.variable!==v){toast('El archivo cargado contiene una sola variable. Volvé a demo para ver las demás.');return;}state.variable=v;render();}
function summary(){const rows=visibleSeries(),annual=annualSummaries(rows,state.variable),complete=annual.filter(r=>r.complete);const first=complete[0],last=complete.at(-1),delta=complete.length>=2?last.value-first.value:null;return {rows,annual,first,last,delta,trend:assessTrend(annual,{observed:!!state.imported}),quality:summarizeQuality(rows)};}
function renderEvidence(){const s=summary(),meta=VARIABLES[state.variable],bbox=MAP_AREAS.find(a=>a.id===state.area).bbox;let significance=state.imported?s.trend.reason:'No se evalúa: son datos sintéticos. No hay evidencia de cambio observado.';if(s.trend.eligible)significance+=` p = ${fmt(s.trend.p,4)}; prueba exploratoria sin corrección por múltiples análisis.`;const change=Number.isFinite(s.delta)?`${s.delta>=0?'+':''}${fmt(s.delta,meta.decimals)} ${annualUnit(state.variable)} entre ${s.first.year} y ${s.last.year}.`:'Se necesitan al menos dos años completos para comparar.';const slope=Number.isFinite(s.trend.slope)?`Sen descriptivo: ${fmt(s.trend.slope,meta.decimals+1)} (${annualUnit(state.variable)}) por año.`:'';$('#evidence').innerHTML=[['¿Qué cambió?',`${esc(meta.name)}. ${state.imported?'Serie importada, pendiente de revisión de procedencia.':'Variación ilustrativa de una serie sintética.'}`],['¿Dónde?',`<strong>${esc(AREAS[state.area].name)}</strong> · área de ejemplo.<br>${Math.abs(bbox[0])}–${Math.abs(bbox[2])}° O · ${Math.abs(bbox[1])}–${Math.abs(bbox[3])}° S.`],['¿Cuánto?',`<strong>${esc(change)}</strong> ${esc(slope)}`],['¿Es significativo?',esc(significance)]].map(([h,p],i)=>`<article class="question"><span class="question-number">0${i+1}</span><div><h3>${h}</h3><p>${p}</p></div></article>`).join('');$('#quality-message').textContent=`${s.quality.valid} de ${s.quality.total} meses utilizables · ${s.quality.excluded} excluidos · ${s.trend.n} años completos. ${state.imported?'La procedencia fue declarada por quien cargó el archivo. '+s.trend.warning:'Demo: la significancia sobre el territorio está deshabilitada.'}${state.variable==='soil'?' SMAP: desde abril de 2015; 2015 no es un año completo.':''}`;}
function renderChart(){const rows=visibleSeries(),meta=VARIABLES[state.variable],valid=rows.filter(isUsable);$('#chart-title').textContent=({ndvi:'La vegetación, mes a mes',evi:'Otra mirada sobre la vegetación',precip:'El pulso de la precipitación',hotspots:'El registro de señales térmicas',soil:'El agua en la superficie del suelo'})[state.variable];$('#series-label').textContent=state.imported?'Serie importada · sin verificación externa':'Serie sintética · no observada';$('#series-unit').textContent=unit(state.variable);$('#sample-count').textContent=`${valid.length} meses utilizables de ${rows.length} · ${labelMode()}`;$('#chart').hidden=state.table;$('#data-table').hidden=!state.table;$('#toggle-table').textContent=state.table?'Ver gráfico ↗':'Ver tabla ↗';
 $('#data-table').innerHTML=`<table><caption>${esc(meta.name)} · ${esc(labelMode())}</caption><thead><tr><th>Mes</th><th>${esc(unit(state.variable))}</th><th>Calidad</th><th>Cobertura</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${r.date}</td><td>${fmt(r.value,meta.decimals)}</td><td>${({demo:'Sintético',valid:'Válido declarado',suspect:'Sospechoso',missing:'Faltante'})[r.quality]}</td><td>${fmt(r.coverage*100,0)}%</td></tr>`).join('')}</tbody></table>`;
 if(!valid.length){$('#chart').innerHTML='<div class="empty-state">No hay meses con calidad y cobertura suficientes para este período.</div>';return;}
 const width=Math.max(300,$('#chart').clientWidth),height=250,left=52,right=18,top=18,bottom=35;const low=Math.min(...valid.map(r=>r.value)),high=Math.max(...valid.map(r=>r.value));const padding=(high-low)*.16||.1;const min=Math.max(state.variable==='ndvi'||state.variable==='evi'?-1:0,low-padding),max=high+padding;const w=width-left-right,h=height-top-bottom;const x=i=>left+i*w/Math.max(rows.length-1,1),y=v=>top+(max-v)/(max-min)*h;let d='',active=false;rows.forEach((r,i)=>{if(!isUsable(r)){active=false;return;}d+=`${active?'L':'M'}${x(i).toFixed(2)},${y(r.value).toFixed(2)} `;active=true;});let grid='';for(let k=0;k<5;k++){const value=min+(max-min)*k/4;grid+=`<line x1="${left}" x2="${width-right}" y1="${y(value)}" y2="${y(value)}" stroke="#e9eee3" stroke-dasharray="3 5"/><text x="${left-12}" y="${y(value)+3}" text-anchor="end" font-size="10" fill="#6f8064">${fmt(value,meta.decimals===0?0:meta.decimals===3?2:0)}</text>`;}const ticks=Math.min(6,rows.length);for(let k=0;k<ticks;k++){const i=Math.round(k*(rows.length-1)/(ticks-1||1));grid+=`<text x="${x(i)}" y="${height-10}" text-anchor="middle" font-size="10" fill="#9ca891">${rows[i].date.slice(0,4)}${rows.length<=12?'-'+rows[i].date.slice(5):''}</text>`;}
 $('#chart').innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="${esc(meta.name)}. ${esc(labelMode())}. Usá Ver tabla para acceder a todos los valores.">${grid}<path d="${d}" fill="none" stroke="#508768" stroke-width="2.2" stroke-linejoin="round"/><line id="crosshair" y1="${top}" y2="${height-bottom}" stroke="#8baf72" stroke-dasharray="3 3" opacity="0"/><circle id="chart-point" r="4" fill="#3c7654" stroke="white" stroke-width="2" opacity="0"/></svg><div class="chart-tooltip" hidden></div>`;
 let index=0;const showPoint=i=>{index=i;const row=rows[i],tip=$('.chart-tooltip');$('#crosshair').setAttribute('x1',x(i));$('#crosshair').setAttribute('x2',x(i));$('#crosshair').setAttribute('opacity','1');$('#chart-point').setAttribute('cx',x(i));$('#chart-point').setAttribute('cy',isUsable(row)?y(row.value):top);$('#chart-point').setAttribute('opacity',isUsable(row)?'1':'0');tip.hidden=false;tip.style.left=`${Math.min(65,Math.max(4,x(i)/width*100-8))}%`;tip.textContent=`${row.date} · ${isUsable(row)?fmt(row.value,meta.decimals)+' '+unit(state.variable):'Sin dato utilizable'} · ${state.imported?'Importado':'DEMO'}`;};$('#chart').onpointermove=e=>{const rect=$('#chart svg').getBoundingClientRect();showPoint(Math.min(rows.length-1,Math.max(0,Math.round(((e.clientX-rect.left)/rect.width*width-left)/w*(rows.length-1)))));};$('#chart').onpointerleave=()=>{if($('.chart-tooltip'))$('.chart-tooltip').hidden=true;};$('#chart').onkeydown=e=>{if(['ArrowRight','ArrowLeft'].includes(e.key)){e.preventDefault();showPoint(Math.min(rows.length-1,Math.max(0,index+(e.key==='ArrowRight'?1:-1))));}};
}
function renderAnomalies(){const meta=VARIABLES[state.variable],rows=seasonalAnomalies(fullSeries().filter(p=>+p.date.slice(0,4)===state.compare),fullSeries());const width=360,height=220,left=34,top=20,mid=103,bottom=174;const max=Math.max(...rows.map(r=>Math.abs(r.anomaly??0)),.001)*1.22;let markup=`<text x="${left}" y="12" fill="#99a58d" font-size="9">Δ ${esc(unit(state.variable))} · ${state.imported?'importado':'demo'}</text>`;for(const mult of [-1,0,1]){const y=mid-mult*62;markup+=`<line x1="${left}" y1="${y}" x2="347" y2="${y}" stroke="${mult===0?'#d9e2cf':'#edf1e8'}" ${mult===0?'':'stroke-dasharray="3 4"'}/><text x="${left-6}" y="${y+3}" text-anchor="end" font-size="8" fill="#9fa992">${fmt(mult*max,meta.decimals===0?0:meta.decimals===3?2:0)}</text>`;}for(let m=1;m<=12;m++){const r=rows.find(p=>+p.date.slice(5)===m);const x=left+(m-1)*26+5;const value=r?.anomaly;const usable=Number.isFinite(value);if(usable){const h=Math.max(.7,Math.abs(value)/max*62);markup+=`<rect x="${x}" y="${value>=0?mid-h:mid}" width="14" height="${h}" rx="2" fill="${value>=0?'#227b65':'#bd8951'}"><title>${fullMonths[m-1]} ${state.compare}: ${fmt(value,meta.decimals)} ${unit(state.variable)}. ${labelMode()}.</title></rect>`;}else markup+=`<text x="${x+7}" y="${mid+3}" text-anchor="middle" fill="#b9c1af" font-size="9">×</text>`;markup+=`<text x="${x+7}" y="${bottom}" fill="#939f88" text-anchor="middle" font-size="9">${months[m-1]}</text>`;}const usable=rows.filter(r=>Number.isFinite(r.anomaly));markup+=`<text x="${left}" y="205" fill="#99a58d" font-size="9">${usable.length}/12 meses comparables${usable.length<12?' · × sin dato o referencia insuficiente':''}</text>`;$('#anomaly-chart').innerHTML=`<svg viewBox="0 0 ${width} ${height}" role="img" aria-label="Diferencias mensuales de ${state.compare} respecto de 2015 a 2020, ${esc(labelMode())}">${markup}</svg>`;}
function render(){syncYears();$('#area').value=state.area;$('#area').disabled=!!state.imported;map.setSelection(state.area);map.setLayer(state.variable);$('#map-layer').textContent=VARIABLES[state.variable].name.toUpperCase();$$('[data-variable]').forEach(b=>{b.classList.toggle('active',b.dataset.variable===state.variable);b.setAttribute('aria-pressed',String(b.dataset.variable===state.variable));b.disabled=!!state.imported&&b.dataset.variable!==state.variable;});$('#mode-title').textContent=state.imported?'Estás explorando datos importados':'Estás explorando una demostración';$('#mode-detail').textContent=state.imported?'Procedencia declarada por el usuario; no verificada de forma independiente.':'Las series son sintéticas. No describen cambios ambientales observados.';$('#evidence-mode').textContent=state.imported?'IMPORTADO':'DEMO';renderMetrics();renderEvidence();renderChart();renderAnomalies();}
const sourceCards=[{name:'Vegetación',product:'MODIS · MOD13A2.061',desc:'NDVI y EVI en compuestos de 16 días. Filtrar píxeles por calidad, aplicar escala y ponderar la agregación mensual antes de comparar.',tags:['1 km','16 días','NDVI / EVI'],links:[['Producto NASA','https://doi.org/10.5067/MODIS/MOD13A2.061']]},{name:'Precipitación',product:'GPM · IMERG Final V07',desc:'Producto mensual GPM_3IMERGM. Convertir la tasa nativa en mm/h a acumulados mensuales usando las horas reales del mes.',tags:['0,1°','Mensual','Final Run'],links:[['NASA GPM','https://gpm.nasa.gov/data/imerg']]},{name:'Actividad térmica',product:'VIIRS S-NPP · FIRMS',desc:'La demo usa conteos sintéticos de un sensor conceptual. Las detecciones reales requieren filtros, cobertura y sensor constante. No son incendios únicos ni hectáreas quemadas.',tags:['375 m','Detecciones','Sin alerta operativa'],links:[['NASA FIRMS','https://firms.modaps.eosdis.nasa.gov/'],['CONAE','https://catalogos5.conae.gov.ar/catalogoFocos/default.aspx']]},{name:'Humedad superficial',product:'SMAP · SPL3SMP V009',desc:'Producto radiométrico diario a 36 km. Abril de 2015 es el primer mes completo de la serie posible. Revisar retrieval QA, agua y congelamiento.',tags:['36 km','Desde 2015','m³/m³'],links:[['NASA / NSIDC','https://nsidc.org/data/spl3smp/versions/9']]}];
$('#sources-grid').innerHTML=sourceCards.map(s=>`<article class="panel source-card"><div class="eyebrow">${s.product}</div><h3>${s.name}</h3><p>${s.desc}</p><div class="source-meta">${s.tags.map(t=>`<span>${t}</span>`).join('')}</div><div class="source-links">${s.links.map(([label,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${label} ↗</a>`).join('')}</div></article>`).join('');
async function loadCatalog(){try{const response=await fetch('./data/nasa-catalog.json');if(!response.ok)throw Error();const data=await response.json();const date=new Date(data.completedAt||data.generatedAt).toLocaleDateString('es-AR');const count=data.products?.length??0;$('#catalog-state').innerHTML=data.status==='verified_catalog'?`<strong>Catálogo NASA consultado el ${esc(date)}.</strong> ${count} colecciones con consultas y respuestas guardadas. No se descargaron ni procesaron series ambientales observadas.<br><a href="./data/nasa-catalog.json" download>Descargar manifiesto de procedencia ↓</a> · <a href="https://cmr.earthdata.nasa.gov/search/site/docs/search/api.html" target="_blank" rel="noopener noreferrer">API pública CMR ↗</a>`:'El catálogo no pudo verificarse por completo. Las series continúan en modo demo.';}catch{$('#catalog-state').textContent='No se pudo cargar el manifiesto local. Las series continúan en modo demo; no se afirma conexión a observaciones.';}}
$$('.nav-item').forEach(b=>b.onclick=()=>navigate(b.dataset.page));$('#mode-link').onclick=()=>navigate('sources');$('#method-link').onclick=()=>navigate('method');$('.brand').onclick=e=>{e.preventDefault();navigate('overview');};$('#area').onchange=e=>{state.area=e.target.value;render();};$('#start-year').onchange=e=>{state.start=+e.target.value;if(state.start>state.end){state.end=state.start;toast('Ajustamos el año final para mantener un período válido.');}render();};$('#end-year').onchange=e=>{state.end=+e.target.value;if(state.end<state.start){state.start=state.end;toast('Ajustamos el año inicial para mantener un período válido.');}render();};$('#compare-year').onchange=e=>{state.compare=+e.target.value;renderAnomalies();};$$('[data-variable]').forEach(b=>b.onclick=()=>selectVariable(b.dataset.variable));$('#zoom-in').onclick=()=>map.zoomIn();$('#zoom-out').onclick=()=>map.zoomOut();$('#zoom-reset').onclick=()=>map.reset();$('#reset').onclick=()=>{if(state.imported){state.start=+state.imported.points[0].date.slice(0,4);state.end=+state.imported.points.at(-1).date.slice(0,4);}else Object.assign(state,{area:'seco',variable:'ndvi',start:2015,end:2025});state.compare=state.end;map.reset();render();toast('Filtros restablecidos.');};$('#toggle-table').onclick=()=>{state.table=!state.table;renderChart();};
$('#download-csv').onclick=()=>{const csvCell=v=>'"'+(typeof v==='string'&&/^[\s]*[=+@-]/.test(v)?"'"+v:String(v??'')).replaceAll('"','""')+'"';const rows=seasonalAnomalies(visibleSeries(),fullSeries());const header=['modo','area','variable','mes','valor','unidad','calidad','cobertura','anomalia_absoluta','referencia','fuente_declarada','producto'];const output=[header,...rows.map(r=>[state.imported?'importado_no_verificado':'demo_sintetico',state.area,state.variable,r.date,r.value,unit(state.variable),r.quality,r.coverage,r.anomaly,'2015-2020',state.imported?.source.url??'Generador sintético local',state.imported?.source.product??'No observado'])].map(row=>row.map(csvCell).join(',')).join('\r\n');download(`terramind-${state.imported?'importado':'DEMO'}-${state.variable}-${state.area}.csv`,'\uFEFF'+output,'text/csv;charset=utf-8');toast('CSV exportado con modo y procedencia explícitos.');};
$('#export-report').onclick=()=>{const s=summary();const text=`# TerraMind / SIGMA EARTH\n\nModo: ${labelMode()}\nÁrea: ${AREAS[state.area].name}, ventana ilustrativa de 1° × 1°\nVariable: ${VARIABLES[state.variable].name}\nPeríodo: ${state.start}–${state.end}\nReferencia mensual: 2015–2020 (6 años, no normal climatológica)\n\n${state.imported?'Procedencia declarada, sin verificación independiente.':'DATOS SINTÉTICOS: no son observaciones NASA ni evidencia sobre el territorio.'}\n\nMeses utilizables: ${s.quality.valid}/${s.quality.total}\nAños completos: ${s.trend.n}\nSen descriptivo: ${fmt(s.trend.slope,5)} (${annualUnit(state.variable)}) por año\nMann–Kendall: ${s.trend.reason}\n${s.trend.eligible?'p exploratorio: '+s.trend.p:''}\n\n## Límites\nNo se atribuyen causas. Focos no equivalen a incendios únicos o superficie quemada. NDVI no mide directamente deforestación. Sin predicciones ni alertas operativas.\n\nFuente: ${state.imported?state.imported.source.url:'Generador sintético local; catálogo de productos NASA por separado.'}\n${state.imported?'Producto: '+state.imported.source.product+'\nVersión: '+state.imported.source.version+'\nDescarga: '+state.imported.source.downloadedAt+'\nAgregación: '+state.imported.source.aggregation+'\nQA: '+state.imported.source.qualityFilter:''}\n`;download(`TerraMind-${state.imported?'importado':'DEMO'}-resumen.md`,text,'text/markdown;charset=utf-8');toast('Resumen exportado con los límites del análisis.');};
$('#import-file').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024)throw Error('El archivo supera 5 MB.');const input=JSON.parse(await file.text());const result=validateDataset(input);if(!result.valid)throw Error(result.errors.join('\n'));state.imported=result.dataset;Object.assign(state,{variable:result.dataset.variable,area:result.dataset.area,start:+result.dataset.points[0].date.slice(0,4),end:+result.dataset.points.at(-1).date.slice(0,4)});state.compare=state.end;$('#import-status').textContent=`Serie aceptada: ${result.dataset.points.length} meses. Fuente declarada: ${result.dataset.source.title}\nProducto: ${result.dataset.source.product} · versión ${result.dataset.source.version}\nAgregación: ${result.dataset.source.aggregation}\nFiltro QA: ${result.dataset.source.qualityFilter}\nLa validación del formato no certifica autenticidad ni calidad científica.`;render();toast('Serie cargada. Procedencia declarada, sin verificación independiente.');}catch(error){$('#import-status').textContent='No se importó la serie:\n'+error.message;toast('Revisá los errores de importación.');}finally{e.target.value='';}};
$('#return-demo').onclick=()=>{state.imported=null;Object.assign(state,{variable:'ndvi',area:'seco',start:2015,end:2025,compare:2025});$('#import-status').textContent='Volviste a la demostración. El archivo importado se descartó de esta sesión.';render();toast('Modo demo restablecido.');};
$('#download-schema').onclick=()=>download('TerraMind-formato-de-importacion.txt',`TerraMind · contrato de importación v1\n\nNo hay valores observacionales en este archivo. Reemplazá todos los marcadores con tus datos realmente procesados.\n\n{\n  "schemaVersion": 1,\n  "kind": "observations",\n  "variable": "ndvi",\n  "area": "seco",\n  "units": "1",\n  "source": {\n    "title": "Título de la fuente",\n    "url": "https://URL-DEL-PRODUCTO",\n    "product": "ID del producto",\n    "version": "Versión",\n    "downloadedAt": "YYYY-MM-DD",\n    "aggregation": "Método espacial y temporal, área exacta, escala y unidades",\n    "qualityFilter": "Filtro QA aplicado"\n  },\n  "points": [\n    {"date": "YYYY-MM", "value": null, "coverage": 0, "quality": "missing"}\n  ]\n}\n\nVariables/unidades: ndvi=1, evi=1, precip=mm/mes, hotspots=detecciones/mes, soil=m³/m³.\nÁreas: seco, transicion, humedo (ver coordenadas en el mapa).\nquality: valid, suspect o missing. coverage: fracción válida entre 0 y 1.\nLos faltantes deben ser null; no se imputan. SMAP sólo desde 2015-04.\nSe excluye cobertura inferior a 0.8. Mínimo 10 años completos consecutivos para evaluar MK.\nLa procedencia es declarada por quien importa, nunca NASA verificada automáticamente.\n`);
let lastChartWidth=0; new ResizeObserver(entries=>{const width=entries[0]?.contentRect.width;if(width>0&&Math.abs(width-lastChartWidth)>1){lastChartWidth=width;renderChart();}}).observe($('#chart'));
render();navigate('overview',false);loadCatalog();
